#!/usr/bin/env node
// Builds one self-contained HTML file from index.html + css/ + js/, for places that need a single file
// (the claude.ai demo link). The game itself is unchanged: the CSS goes back inside <style>, and every script is
// joined, in the order index.html loads them, inside one function so its names stay private, as in the original.
//
// Usage (from the repo folder):  node tools/bundle.js [output file]      default output: build/pip-and-bo.html
// Needs only Node.js, no packages. build/ is generated by this script (and ignored by git): edit index.html, css/ and
// js/, never build/.
'use strict';
const fs = require('fs'), path = require('path');
const root = path.resolve(__dirname, '..');
const out = path.resolve(process.argv[2] || path.join(root, 'build', 'pip-and-bo.html'));
// files edited on Windows may have CRLF line endings or a byte-order mark; read everything as plain LF text
const read = f => fs.readFileSync(f, 'utf8').replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');
let html = read(path.join(root, 'index.html'));

// 1. stylesheets from this repo go back inline
html = html.replace(/<link rel="stylesheet" href="((?!https?:)[^"]+)">/g, (m, href) =>
  '<style>\n' + read(path.join(root, href)) + '</style>');

// 2. every script (files and inline blocks), in order, becomes one
const STRICT = /^(\/\*[\s\S]*?\*\/\n)?'use strict';(\n|$)/; // each script starts with an optional title comment and 'use strict' (a placeholder file may end right after it)
const parts = [];
let first = -1;
html = html.replace(/<script( src="([^"]+)")?>([\s\S]*?)<\/script>(\n?)/g, (m, a, src, inline, nl, offset) => {
  if (src && /^https?:/.test(src)) throw new Error('external script not supported: ' + src);
  const code = src ? read(path.join(root, src)).replace(/\n$/, '') : inline.replace(/^\n/, '').replace(/\n$/, '');
  if (!STRICT.test(code)) throw new Error((src || 'inline script') + ' must start with \'use strict\';');
  parts.push(src ? code.replace(STRICT, '').replace(/^\n/, '') : code.replace(STRICT, '')); // files have a blank line after it
  if (first < 0) { first = offset; return '\u0000SCRIPT\u0000' + nl; }
  return '';
});
if (first < 0) throw new Error('no scripts found in index.html');
// anything local the two patterns above did not recognise would be missing from the single file: stop instead
const left = (html.match(/<link\b[^>]*\bstylesheet\b[^>]*>|<script\b[^>]*>/gi) || []).filter(t => !/https?:\/\//.test(t));
if (left.length) throw new Error('not inlined (use exactly <link rel="stylesheet" href="..."> and <script src="..."></script>): ' + left.join(' '));
// 3. the 3D kit (loaded on demand in the real game): its files go in as one function the loader runs after three.js,
//    and three.js itself as text the loader runs from a blob only when a 3D level opens (js/3d/k3d.js)
const k3d = read(path.join(root, 'js/3d/k3d.js'));
const kitFiles = JSON.parse(k3d.match(/files: (\[[^\]]*\])/)[1].replace(/'/g, '"').replace(/\s+/g, ' '));
const libSrc = k3d.match(/lib: '([^']+)'/)[1];
const kitParts = kitFiles.map(f => { const c = read(path.join(root, f)).replace(/\n$/, ''); if (!STRICT.test(c)) throw new Error(f + ' must start with \'use strict\';'); return c.replace(STRICT, ''); });
parts.push('K3D.kitInline = () => {\n' + kitParts.join('\n') + '\n};');
const three = '<script>\nwindow.__k3dInline = { ' + JSON.stringify(libSrc) + ': ' + JSON.stringify(read(path.join(root, libSrc))).replace(/<\//g, '<\\/') + ' };\n</script>\n';
const script = three + '<script>\n(() => {\n\'use strict\';\n' + parts.join('\n') + '\n})();\n</script>';
html = html.replace('\u0000SCRIPT\u0000', () => script);

fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, html);
console.log('Wrote ' + path.relative(process.cwd(), out) + ' (' + (html.length / 1024 / 1024).toFixed(2) + ' MB, ' + parts.length + ' scripts joined)');
